using Godot;
using System;
using System.Linq;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class PowderGeometryOperations:RefCounted
{
    private readonly PhysicsSettingsOperations _settings=new();private readonly PowderSourceOperations _source=new();private static Variant Get(Settings values,string key,Variant fallback=default)=>values.TryGetValue(key,out var value)?value:fallback;
    public GArray variants(Settings values,Settings cache){int shape=Math.Clamp(Get(values,"powder_grain_shape",1).AsInt32(),0,4),detail=Math.Clamp(Get(values,"powder_render_detail",1).AsInt32(),0,2);double variation=Math.Clamp(Get(values,"powder_shape_variation",.25).AsDouble(),0,1);long seed=Get(values,"powder_visual_seed",17).AsInt64();var custom=new Godot.Collections.Array<Mesh>();if(shape==4)foreach(string name in new[]{"powder_custom_mesh","powder_custom_mesh_2","powder_custom_mesh_3"}){var value=Get(values,name);if(value.VariantType==Variant.Type.Object&&value.AsGodotObject() is Mesh mesh)custom.Add(mesh);else if(value.VariantType==Variant.Type.String&&value.AsString().Length>0&&ResourceLoader.Exists(value.AsString())&&ResourceLoader.Load(value.AsString()) is Mesh loaded)custom.Add(loaded);}var identities=new GArray();foreach(var mesh in custom)identities.Add(_settings.canonical(mesh));long key=(long)GD.Hash(new GArray{shape,detail,variation,seed,Get(values,"powder_variants",3),identities});if(cache.ContainsKey(key))return cache[key].AsGodotArray();var result=new Godot.Collections.Array<Mesh>();int count=custom.Count>0?custom.Count:Math.Clamp(Get(values,"powder_variants",3).AsInt32(),1,8);for(int i=0;i<count;i++){Mesh mesh;if(custom.Count>0)mesh=normalized(custom[i]);else if(shape==0)mesh=new SphereMesh{Radius=1,Height=2,RadialSegments=new[]{6,10,16}[detail],Rings=new[]{3,5,8}[detail]};else if(shape==3)mesh=deform(new CylinderMesh{TopRadius=.45f,BottomRadius=.75f,Height=1.65f,RadialSegments=i%2==0?4:6,Rings=1},variation,seed+i*733);else mesh=deform(new SphereMesh{Radius=1,Height=2,RadialSegments=new[]{5,7,10}[detail],Rings=new[]{2,3,4}[detail]},variation*(shape==2?1:.5),seed+i*733);result.Add(mesh);}GD.Load<GDScript>("res://scripts/actors/physics/powder/powder_geometry.gd").Call("_built");if(cache.Count>=32)cache.Remove(cache.Keys.First());cache[key]=result;return Variant.From(result).AsGodotArray();}
    public Mesh normalized(Mesh mesh){var result=new ArrayMesh();var bounds=mesh.GetAabb();float extent=Math.Max(.00001f,bounds.Size.Length()*.5f);for(int surface=0;surface<mesh.GetSurfaceCount();surface++){if(mesh is ArrayMesh arrayMesh&&arrayMesh.SurfaceGetPrimitiveType(surface)!=Mesh.PrimitiveType.Triangles)continue;var arrays=mesh.SurfaceGetArrays(surface).Duplicate(true);var points=arrays[(int)Mesh.ArrayType.Vertex].AsVector3Array();for(int i=0;i<points.Length;i++)points[i]=(points[i]-bounds.GetCenter())/extent;arrays[(int)Mesh.ArrayType.Vertex]=points;result.AddSurfaceFromArrays(Mesh.PrimitiveType.Triangles,arrays);}return result;}
    public Mesh deform(Mesh mesh,double amount,long seed){var source=mesh.SurfaceGetArrays(0);var points=source[(int)Mesh.ArrayType.Vertex].AsVector3Array();var indices=source[(int)Mesh.ArrayType.Index].AsInt32Array();var uv=source[(int)Mesh.ArrayType.TexUV].AsVector2Array();using var rng=_source.rng_for(seed,47);var stretch=new Vector3(rng.RandfRange(.75f,1),rng.RandfRange(.65f,1),rng.RandfRange(.7f,1));for(int i=0;i<points.Length;i++){var point=points[i];double noise=Math.Sin(point.X*9.7+point.Y*13.1+point.Z*7.3+seed)*Math.Sin(point.X*3.1-point.Y*6.7+point.Z*4.3+seed*.17);points[i]=point*stretch*(float)(1+noise*amount*.27);}var surface=new SurfaceTool();surface.Begin(Mesh.PrimitiveType.Triangles);surface.SetSmoothGroup(uint.MaxValue);foreach(int index in indices){surface.SetUV(uv[index]);surface.AddVertex(points[index]);}surface.GenerateNormals();surface.GenerateTangents();return surface.Commit();}
}
